#include <iostream>
struct Base {
    virtual void ping() { std::cout << "B"; }
};
struct Derived : Base {
    void ping() override { std::cout << "D"; }
};
int main() {
    Derived d;
    Base b = d;
    Base& r = d;
    b.ping();
    r.ping();
}

#include <iostream>
template<typename T>
int counter() {
    static int c = 0;
    return ++c;
}
int main() {
    std::cout << counter<int>() << counter<int>() << counter<double>();
}

